        // keep addresses reasonable (avoid zero address for nft to still be admissible)
        // but allow wide domain; only bound feeRate to <= type(uint16).max (already), but ensure feeRate within allowed limit to let initialize succeed normally in reference
        // allow both baseToken zero/non-zero
        vm.assume(_feeRate <= 5000); // admissible per contract precondition

        // call initialize and observe whether it returned successfully. If it returns, reference guarantees initialized()==true.
